import{_ as r,C as c,o as t,c as o,a2 as e,b as s,w as d,a as i,E as l,a3 as h}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Bandwidth Monitor for Pterodactyl","description":"Per-server bandwidth monitoring and enforcement for Pterodactyl — tc speed caps, day/week/month quotas, quota-driven throttle and suspend, all managed from the panel.","frontmatter":{"title":"Bandwidth Monitor for Pterodactyl","description":"Per-server bandwidth monitoring and enforcement for Pterodactyl — tc speed caps, day/week/month quotas, quota-driven throttle and suspend, all managed from the panel.","head":[["meta",{"name":"og:title","content":"Bandwidth Monitor for Pterodactyl — Panel-Native Traffic Control"}],["meta",{"name":"og:description","content":"A Blueprint panel addon plus a Go node agent that gives every game server speed caps, multi-period quotas, reports and predictions — enforced with tc on each Wings node."}]]},"headers":[],"relativePath":"pterodactyl-bandwidth-monitor/index.md","filePath":"pterodactyl-bandwidth-monitor/index.md","lastUpdated":1785221274000}'),p={name:"pterodactyl-bandwidth-monitor/index.md"};function v(g,a,u,b,m,y){const n=c("Mermaid");return t(),o("div",null,[a[1]||(a[1]=e('<h1 id="bandwidth-monitor-for-pterodactyl" tabindex="-1" data-v-0c391ac0>Bandwidth Monitor for Pterodactyl <a class="header-anchor" href="#bandwidth-monitor-for-pterodactyl" aria-label="Permalink to &quot;Bandwidth Monitor for Pterodactyl&quot;" data-v-0c391ac0>​</a></h1><p data-v-0c391ac0><strong data-v-0c391ac0>Panel-native bandwidth monitoring and enforcement for Pterodactyl</strong> — a Blueprint addon on the panel plus a Go agent (<code data-v-0c391ac0>bandwidth-noded</code>) on every Wings node. It counts inbound/outbound traffic per game server, enforces per-server speed caps and day/week/month quotas with Linux <code data-v-0c391ac0>tc</code>, and surfaces dashboards, reports and usage predictions directly in your admin area.</p><div class="tip custom-block" style="margin-top:1.5rem;" data-v-0c391ac0><p data-v-0c391ac0><strong data-v-0c391ac0>📡 Built for PingLess Studios</strong><br data-v-0c391ac0><a href="https://studio.pingless.org" target="_blank" rel="noreferrer" data-v-0c391ac0>studio.pingless.org</a> · Panel addon + node agent, installed separately</p></div><hr data-v-0c391ac0><h2 id="architecture" tabindex="-1" data-v-0c391ac0>Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;" data-v-0c391ac0>​</a></h2>',5)),(t(),s(h,null,{default:d(()=>[l(n,{id:"mermaid-15",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Panel%5B%22Pterodactyl%20Panel%22%5D%0A%20%20%20%20%20%20%20%20ADDON%5B%22Bandwidth%20Monitor%20addon%3Cbr%2F%3E(Blueprint%3A%20pterodactylbandwidth)%22%5D%0A%20%20%20%20%20%20%20%20DB%5B(%22bandwidth_*%20tables%3Cbr%2F%3Etokens%20%C2%B7%20limits%20%C2%B7%20events%20%C2%B7%20rollups%22)%5D%0A%20%20%20%20%20%20%20%20UI%5B%22Admin%20UI%3Cbr%2F%3EDashboard%20%C2%B7%20Nodes%20%C2%B7%20Servers%20%C2%B7%20Reports%20%C2%B7%20Events%20%C2%B7%20Settings%22%5D%0A%20%20%20%20%20%20%20%20ADDON%20--%3E%20DB%0A%20%20%20%20%20%20%20%20UI%20--%3E%20ADDON%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Node1%5B%22Wings%20Node%201%22%5D%0A%20%20%20%20%20%20%20%20AGENT1%5B%22bandwidth-noded%22%5D%0A%20%20%20%20%20%20%20%20TC1%5B%22tc%20(HTB%20%2B%20ingress%20police)%22%5D%0A%20%20%20%20%20%20%20%20C1%5B%22Server%20containers%22%5D%0A%20%20%20%20%20%20%20%20AGENT1%20--%3E%20TC1%20--%3E%20C1%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Node2%5B%22Wings%20Node%202%22%5D%0A%20%20%20%20%20%20%20%20AGENT2%5B%22bandwidth-noded%22%5D%0A%20%20%20%20%20%20%20%20TC2%5B%22tc%20(HTB%20%2B%20ingress%20police)%22%5D%0A%20%20%20%20%20%20%20%20C2%5B%22Server%20containers%22%5D%0A%20%20%20%20%20%20%20%20AGENT2%20--%3E%20TC2%20--%3E%20C2%0A%20%20%20%20end%0A%0A%20%20%20%20AGENT1%20--%3E%7C%22register%20(one-time%20pairing)%22%7C%20ADDON%0A%20%20%20%20AGENT1%20--%3E%7C%22heartbeat%20every%2060s%22%7C%20ADDON%0A%20%20%20%20AGENT1%20--%3E%7C%22events%20%2B%20suspend%20callbacks%22%7C%20ADDON%0A%20%20%20%20ADDON%20--%3E%7C%22limits%20push%20(PUT%20%2Flimits)%22%7C%20AGENT1%0A%20%20%20%20ADDON%20--%3E%7C%22stats%20%2B%20history%20pulls%22%7C%20AGENT1%0A%20%20%20%20AGENT2%20--%3E%7C%22register%20%C2%B7%20heartbeat%20%C2%B7%20events%22%7C%20ADDON%0A%20%20%20%20ADDON%20--%3E%7C%22limits%20push%20%C2%B7%20stats%20pulls%22%7C%20AGENT2%0A"})]),fallback:d(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e(`<p data-v-0c391ac0>The node agent authenticates to the panel with a per-node 64-hex bearer token; the panel uses the same token when calling back into the node. The wire protocol on both sides is a single documented API contract with a <code data-v-0c391ac0>{success, data, error, meta}</code> envelope everywhere.</p><hr data-v-0c391ac0><h2 id="key-features" tabindex="-1" data-v-0c391ac0>Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;" data-v-0c391ac0>​</a></h2><ul data-v-0c391ac0><li data-v-0c391ac0><strong data-v-0c391ac0>🚦 Per-server speed caps (RX and TX).</strong> Set inbound and outbound Mbps limits per server. Enforced on each container&#39;s veth with <code data-v-0c391ac0>tc</code> HTB for egress and an ingress qdisc with policing for RX — kernel-level, no userspace throttling.</li><li data-v-0c391ac0><strong data-v-0c391ac0>📅 Day / week / month quotas, per direction.</strong> Independent RX and TX quotas for each period, in GiB. Periods reset at calendar boundaries (midnight, Monday 00:00, 1st 00:00) in a configurable timezone.</li><li data-v-0c391ac0><strong data-v-0c391ac0>⚖️ Configurable exceed actions.</strong> When a quota trips, the node applies the server&#39;s action: <strong data-v-0c391ac0>throttle</strong> (re-apply <code data-v-0c391ac0>tc</code> at low throttle speeds), <strong data-v-0c391ac0>suspend</strong> (panel callback suspends the Pterodactyl server, then throttle to 1 Mbps), or <strong data-v-0c391ac0>log-only</strong> (event recorded, no enforcement).</li><li data-v-0c391ac0><strong data-v-0c391ac0>🔑 Per-node pairing tokens.</strong> Every Pterodactyl node gets a 64-hex pairing token on the Nodes page — viewable and resettable from the UI. Resetting a token kills the old one immediately.</li><li data-v-0c391ac0><strong data-v-0c391ac0>🖥️ Native admin UI.</strong> Six AdminLTE pages inside your panel — Dashboard, Nodes, Servers, Reports, Events, Settings — with bundled Chart.js dashboards (fleet bandwidth over time, top consumers).</li><li data-v-0c391ac0><strong data-v-0c391ac0>📈 Hourly + daily rollups.</strong> The panel polls each online node for counters every minute and stores per-server hourly and daily usage buckets for fast charting and reporting.</li><li data-v-0c391ac0><strong data-v-0c391ac0>🔮 Usage predictions.</strong> Linear projection per server (current usage + average rate × remaining time, cross-checked against the 7-day daily average) surfaces &quot;projected to exceed quota on &lt;date&gt;&quot; before it happens.</li><li data-v-0c391ac0><strong data-v-0c391ac0>📄 Reports with CSV export.</strong> Date-ranged per-server usage reports, downloadable as CSV for billing or finance tooling.</li><li data-v-0c391ac0><strong data-v-0c391ac0>🧩 Server build-config integration.</strong> Bandwidth fields (enabled, speed caps, six quota fields, exceed action, throttle speeds) are added directly to the server build configuration, with admin defaults from <strong data-v-0c391ac0>Settings</strong> prefilling every new server.</li><li data-v-0c391ac0><strong data-v-0c391ac0>💾 Crash-safe enforcement.</strong> Counters, limits and the outbound event queue persist in SQLite on the node; <code data-v-0c391ac0>tc</code> rules are re-applied on boot, so enforcement survives agent restarts.</li></ul><hr data-v-0c391ac0><h2 id="quick-install" tabindex="-1" data-v-0c391ac0>Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;" data-v-0c391ac0>​</a></h2><p data-v-0c391ac0>Both halves are installed separately. Panel first, then each node.</p><p data-v-0c391ac0><strong data-v-0c391ac0>Panel (Blueprint):</strong></p><div class="language-bash vp-adaptive-theme" data-v-0c391ac0><button title="Copy Code" class="copy" data-v-0c391ac0></button><span class="lang" data-v-0c391ac0>bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-0c391ac0><code data-v-0c391ac0><span class="line" data-v-0c391ac0><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;" data-v-0c391ac0># place pterodactylbandwidth-v1.0.0.blueprint in /var/www/pterodactyl, then:</span></span>
<span class="line" data-v-0c391ac0><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-0c391ac0>blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;" data-v-0c391ac0> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-0c391ac0> pterodactylbandwidth-v1.0.0</span></span></code></pre></div><p data-v-0c391ac0><strong data-v-0c391ac0>Each Wings node (as root):</strong></p><div class="language-bash vp-adaptive-theme" data-v-0c391ac0><button title="Copy Code" class="copy" data-v-0c391ac0></button><span class="lang" data-v-0c391ac0>bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-0c391ac0><code data-v-0c391ac0><span class="line" data-v-0c391ac0><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-0c391ac0>sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-0c391ac0> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-0c391ac0> install.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;" data-v-0c391ac0>   # from the node-module directory — prompts for panel URL + node token</span></span></code></pre></div><p data-v-0c391ac0>Head to the <a href="./getting-started/quick-start" data-v-0c391ac0>Quick Start</a> for the full ten-minute walkthrough with expected output.</p><hr data-v-0c391ac0><h2 id="how-pairing-works" tabindex="-1" data-v-0c391ac0>How Pairing Works <a class="header-anchor" href="#how-pairing-works" aria-label="Permalink to &quot;How Pairing Works&quot;" data-v-0c391ac0>​</a></h2><ol data-v-0c391ac0><li data-v-0c391ac0><strong data-v-0c391ac0>Token issued.</strong> Open <strong data-v-0c391ac0>Admin → Bandwidth → Nodes</strong>. Every Pterodactyl node gets a row with a generated 64-hex token. The panel stores a bcrypt hash for verification plus an encrypted copy so you can re-view (or reset) it later.</li><li data-v-0c391ac0><strong data-v-0c391ac0>Node installed.</strong> Run <code data-v-0c391ac0>node-module/install.sh</code> as root on the Wings node. It prompts for the panel URL and token, writes <code data-v-0c391ac0>/etc/bandwidth-node/config.yaml</code> and <code data-v-0c391ac0>/etc/bandwidth-node/token</code> (both <code data-v-0c391ac0>0600</code>), and starts the <code data-v-0c391ac0>bandwidth-node</code> systemd service.</li><li data-v-0c391ac0><strong data-v-0c391ac0>Node registers.</strong> The agent calls <code data-v-0c391ac0>POST /api/bandwidth/node/register</code> (retrying with backoff). The panel verifies the bearer token, records the node&#39;s reachable API URL, and flips the node to <strong data-v-0c391ac0>online</strong> in the UI.</li><li data-v-0c391ac0><strong data-v-0c391ac0>Steady state.</strong> The node heartbeats every 60 s with aggregate stats. When limits change in the panel, the heartbeat response carries a bumped <code data-v-0c391ac0>config_version</code> and the node pulls and re-applies them; the panel pushes full limit sets and pulls per-server stats and history in return.</li></ol><hr data-v-0c391ac0><h2 id="comparison-with-bandwidth-manager" tabindex="-1" data-v-0c391ac0>Comparison with Bandwidth Manager <a class="header-anchor" href="#comparison-with-bandwidth-manager" aria-label="Permalink to &quot;Comparison with Bandwidth Manager&quot;" data-v-0c391ac0>​</a></h2><p data-v-0c391ac0>Bandwidth Monitor builds on the same <code data-v-0c391ac0>tc</code>-enforcement philosophy as our standalone <a href="/pingless-studios-docs/bandwidth-manager/" data-v-0c391ac0>Bandwidth Manager</a> project, but is purpose-built for Pterodactyl panels.</p><table tabindex="0" data-v-0c391ac0><thead data-v-0c391ac0><tr data-v-0c391ac0><th data-v-0c391ac0>Capability</th><th style="text-align:center;" data-v-0c391ac0>Bandwidth Monitor for Pterodactyl</th><th style="text-align:center;" data-v-0c391ac0>Bandwidth Manager (standalone)</th></tr></thead><tbody data-v-0c391ac0><tr data-v-0c391ac0><td data-v-0c391ac0>Pterodactyl server ↔ container mapping</td><td style="text-align:center;" data-v-0c391ac0>✅ native (UUID containers)</td><td style="text-align:center;" data-v-0c391ac0>❌ generic Docker labels</td></tr><tr data-v-0c391ac0><td data-v-0c391ac0>Central multi-node admin UI</td><td style="text-align:center;" data-v-0c391ac0>✅ panel pages + dashboards</td><td style="text-align:center;" data-v-0c391ac0>❌ per-host CLI/TUI</td></tr><tr data-v-0c391ac0><td data-v-0c391ac0>Quota periods</td><td style="text-align:center;" data-v-0c391ac0>✅ day / week / month</td><td style="text-align:center;" data-v-0c391ac0>✅ daily</td></tr><tr data-v-0c391ac0><td data-v-0c391ac0>Quotas per direction (RX + TX separately)</td><td style="text-align:center;" data-v-0c391ac0>✅</td><td style="text-align:center;" data-v-0c391ac0>❌</td></tr><tr data-v-0c391ac0><td data-v-0c391ac0>Usage predictions</td><td style="text-align:center;" data-v-0c391ac0>✅</td><td style="text-align:center;" data-v-0c391ac0>❌</td></tr><tr data-v-0c391ac0><td data-v-0c391ac0>Suspend server on exceed</td><td style="text-align:center;" data-v-0c391ac0>✅ via panel API</td><td style="text-align:center;" data-v-0c391ac0>❌ (throttle only)</td></tr><tr data-v-0c391ac0><td data-v-0c391ac0>Reports + CSV export</td><td style="text-align:center;" data-v-0c391ac0>✅</td><td style="text-align:center;" data-v-0c391ac0>✅ CSV export</td></tr><tr data-v-0c391ac0><td data-v-0c391ac0>Multi-node from one screen</td><td style="text-align:center;" data-v-0c391ac0>✅</td><td style="text-align:center;" data-v-0c391ac0>❌</td></tr></tbody></table><blockquote data-v-0c391ac0><p data-v-0c391ac0><strong data-v-0c391ac0>Bottom line:</strong> running a Pterodactyl fleet? Use Bandwidth Monitor — the panel is your single control plane. Running standalone Docker hosts? Bandwidth Manager is the lighter fit.</p></blockquote><hr data-v-0c391ac0><div class="tip custom-block" data-v-0c391ac0><p class="custom-block-title" data-v-0c391ac0>VERIFIED LIVE</p><p data-v-0c391ac0>Both halves were verified end-to-end on a real Pterodactyl panel and Wings node: pairing and registration, live stats flow into the dashboard, a 10 Mbps cap holding a live server at ~9.5 Mbps, a 1 GiB quota exceed triggering a throttle to 5 Mbps with panel events, a weekly quota exceed suspending the server for real, and an admin unthrottle restoring full speed.</p></div><hr data-v-0c391ac0><h2 id="next-steps" tabindex="-1" data-v-0c391ac0>Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;" data-v-0c391ac0>​</a></h2><ul data-v-0c391ac0><li data-v-0c391ac0><strong data-v-0c391ac0><a href="./getting-started/quick-start" data-v-0c391ac0>Quick Start →</a></strong> — From archive to enforced speed cap in ten minutes.</li></ul><hr data-v-0c391ac0><div class="footer-note" data-v-0c391ac0><p data-v-0c391ac0><strong data-v-0c391ac0>Developed for <a href="https://studio.pingless.org" target="_blank" rel="noreferrer" data-v-0c391ac0>PingLess Studios</a></strong></p><p data-v-0c391ac0>Questions or licensing — reach us at <a href="https://studio.pingless.org" target="_blank" rel="noreferrer" data-v-0c391ac0>studio.pingless.org</a>.</p></div>`,27))])}const w=r(p,[["render",v],["__scopeId","data-v-0c391ac0"]]);export{k as __pageData,w as default};
